import React from 'react'; 

// Sample product data 
const products = [ 
  { pid: 'P001', pname: 'Product 1', price: '$10' }, 
  { pid: 'P002', pname: 'Product 2', price: '$20' }, 
  { pid: 'P003', pname: 'Product 3', price: '$30' }, 
  { pid: 'P004', pname: 'Product 4', price: '$40' },
  { pid: 'P004', pname: 'Product 4', price: '$50' }


]; 


const Products = () => { 
  return ( 
    <div> 
      <h1>Products List</h1> 

      <table> 

        <thead> 
          <tr> 
            <th>Product ID</th> 
            <th>Product Name</th> 
            <th>Price</th> 

          </tr> 
        </thead> 


        <tbody> 
          {products.map(product => ( 
            <tr key={product.pid}> 
              <td>{product.pid}</td> 
              <td>{product.pname}</td> 
              <td>{product.price}</td> 
            </tr> 
          ))} 
        </tbody> 

      </table> 

    </div> 
  ); 
}; 

export default Products;
